import 'package:flutter/material.dart';
import 'package:souq_skills/models/trade_proposal.dart';
class ProposalCard extends StatelessWidget { const ProposalCard({required this.proposal, this.onAccept, this.onDecline, this.onCounteroffer, super.key}); final TradeProposal proposal; final VoidCallback? onAccept; final VoidCallback? onDecline; final VoidCallback? onCounteroffer; @override Widget build(BuildContext context) => Card(child: ListTile(title: Text('${proposal.offeredSkill} ⇄ ${proposal.requestedSkill}'), subtitle: Text('${proposal.sessionsMinutes} minutes • ${proposal.deliveryMethod}'), trailing: PopupMenuButton<String>(onSelected: (value) { if (value == 'accept') onAccept?.call(); if (value == 'decline') onDecline?.call(); if (value == 'counter') onCounteroffer?.call(); }, itemBuilder: (context) => const [PopupMenuItem(value: 'accept', child: Text('Accept')), PopupMenuItem(value: 'counter', child: Text('Counter')), PopupMenuItem(value: 'decline', child: Text('Decline'))]))); }
